"""


def node():
    return shutil.which("node") or shutil.which("node.exe")


def run_app(script):
    with tempfile.TemporaryDirectory() as tmp:
        d = Path(tmp)
        (d / "app.js").write_text(script, encoding="utf-8")
        (d / "driver.js").write_text(DRIVER, encoding="utf-8")
        done = subprocess.run([node(), str(d / "driver.js")], capture_output=True, text=True,
                              timeout=60, cwd=d)
        if done.returncode != 0:
            raise AssertionError("app script failed in node: %s" % done.stderr[-800:])
        return json.loads(done.stdout.strip().splitlines()[-1])


class Acceptance(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = TARGET.read_text(encoding="utf-8")
        m = re.search(r'<script[^>]*id=["\']%s["\'][^>]*>(.*?)</script>' % SCRIPT_ID, cls.raw, re.S | re.I)
        cls.script = m.group(1) if m else None
        cls.data, cls.error = None, None
        if cls.script and node():
            try:
                cls.data = run_app(cls.script)
            except (AssertionError, ValueError) as exc:
                cls.error = str(exc)

    def feature(self, name):
        self.assertIsNotNone(self.script, 'no <script id="%s"> block in the page' % SCRIPT_ID)
        if node() is None:
            raise unittest.SkipTest("node is required to run the app script")
        self.assertIsNone(self.error, self.error)
        self.assertIsNone(self.data.get("load_error"), "app script threw while loading: %s" % self.data.get("load_error"))
        self.assertTrue(self.data.get("app"), "the app script must define window.App.features")
        self.assertRegex(self.raw, r'id=["\']panel-%s["\']' % name, "no <section id=\"panel-%s\"> in the page" % name)
        got = self.data["features"].get(name)
        self.assertTrue(got and got.get("present"), "App.features.%s is missing" % name)
        self.assertTrue(got.get("has_model"), "App.features.%s.model must be an object of pure functions" % name)
        self.assertTrue(got.get("has_render"), "App.features.%s.render must be a function" % name)
        self.assertIsNone(got.get("error"), "App.features.%s.model threw: %s" % (name, got.get("error")))
        self.assertFalse(got.get("mutated_input"), "App.features.%s.model mutated the book it was given" % name)
        return got

    # --- the page ---------------------------------------------------------
    def test_page_is_one_self_contained_html_file(self):
        self.assertRegex(self.raw[:400].lower(), r"<!doctype html")
        for pat, why in ((r'src\s*=\s*["\'](https?:)?//', "external src"),
                         (r'href\s*=\s*["\'](https?:)?//', "external href"),
                         (r"@import", "css @import"),
                         (r'url\(\s*["\']?(https?:)?//', "external url()"),
                         (r"\bfetch\s*\(", "network fetch"),
                         (r"XMLHttpRequest", "XHR")):
            self.assertIsNone(re.search(pat, self.raw, re.I), "page must be self-contained: found %s" % why)
