ui_scenario:
// Spreadsheet, what a person does on the page. Runs in the page after the seed; every step
// names an action and what must then be true. State is read through App.store, the contract
// every build honours; controls are found the way a person finds them, by label.
const sleep = ms => new Promise(r => setTimeout(r, ms));
const steps = window.__ui_steps = [];   // shared with the gate, so a timeout keeps what ran
const step = (name, ok, note) => steps.push({ name, ok: !!ok, note: note || '' });
const S = () => App.store.get();
const sheet = () => S().sheets.find(s => s.id === S().active) || S().sheets[0];
const raw = a => (sheet().cells[a] || {}).raw || '';
const tab = async n => { const b = document.querySelector('nav button[data-tab="' + n + '"]'); if (b) b.click(); await sleep(40); return document.getElementById('panel-' + n); };
const setv = (el, v) => { if (!el) return false; el.focus(); el.value = v; el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new Event('change', { bubbles: true })); return true; };
const key = (el, k, extra) => { if (!el) return; const opts = Object.assign({ key: k, code: k, bubbles: true, cancelable: true }, extra || {}); el.dispatchEvent(new KeyboardEvent('keydown', opts)); el.dispatchEvent(new KeyboardEvent('keyup', opts)); };
const label = el => ((el.placeholder || '') + ' ' + (el.name || '') + ' ' + (el.id || '') + ' ' + (el.getAttribute('aria-label') || '') + ' ' + (el.closest('label') ? el.closest('label').textContent : '') + ' ' + (el.previousElementSibling && el.previousElementSibling.tagName === 'LABEL' ? el.previousElementSibling.textContent : '')).toLowerCase();
const inputs = p => [...p.querySelectorAll('input, select, textarea')].filter(i => i.type !== 'hidden');
const field = (p, rx, type) => inputs(p).find(i => (!type || i.tagName === type) && rx.test(label(i)));
const button = (p, rx) => [...p.querySelectorAll('button')].find(b => rx.test(b.textContent.trim()));
const click = async (p, rx) => { const b = button(p, rx); if (b) { b.click(); await sleep(100); } return !!b; };
const text = el => el ? (el.textContent || '') : '';
const has = (el, rx) => !!el && ([...el.querySelectorAll('*')].filter(e => !e.children.length).some(e => rx.test(e.textContent)) || rx.test(el.textContent));   // leaf texts: table cells do not run together
const td = a => document.querySelector('#panel-grid td[data-addr="' + a + '"]');
const cellText = a => text(td(a)).trim();
const type = async (addr, formula) => {          // click a cell, type in the formula bar, Enter
  await tab('grid'); const c = td(addr); if (!c) return false; c.click(); await sleep(60);
  const bar = document.getElementById('formula'); if (!bar) return false;
  setv(bar, formula); key(bar, 'Enter'); await sleep(120); return true;
};
const pick = (sel, rx) => { if (!sel) return false; const o = [...sel.options].find(o => rx.test(o.text) || rx.test(o.value)); if (!o) return false; setv(sel, o.value); return true; };

// 1. the grid shows computed values
await tab('grid');
step('the grid shows A3 = A1+A2 as 30', cellText('A3') === '30', 'A3 reads "' + cellText('A3') + '"');

// 2. type a formula through the formula bar
await type('B5', '=A1*3');
step('typing =A1*3 into B5 via the formula bar stores it and shows 30', raw('B5') === '=A1*3' && cellText('B5') === '30', 'raw ' + raw('B5') + ', shows "' + cellText('B5') + '"');

// 3. an error shows as its code
await type('C5', '=B5/0');
step('a division by zero shows #DIV/0! in the cell', cellText('C5') === '#DIV/0!', 'shows "' + cellText('C5') + '"');

// 4. undo removes the last change
let p = await tab('history');
let undone = await click(p, /^undo$/i) || await click(p, /undo/i);
if (!undone) { await tab('grid'); key(document.activeElement || document.body, 'z', { ctrlKey: true }); await sleep(120); }
step('undo on the History tab removes the last entry', raw('C5') === '' && cellText('C5') === '', 'C5 raw "' + raw('C5') + '"');

// 5. a currency format on B5
await tab('grid'); if (td('B5')) { td('B5').click(); await sleep(60); }
p = await tab('format');
let addrIn = field(p, /cell|addr|range|target/, 'INPUT'); if (addrIn) setv(addrIn, 'B5');
pick(inputs(p).find(i => i.tagName === 'SELECT' && [...i.options].some(o => /currency/i.test(o.text + o.value))), /currency/i);
const dec = field(p, /decimal/); if (dec) setv(dec, '2');
await click(p, /apply|set|format|save/i);
step('a currency format on B5 shows $30.00', cellText('B5') === '$30.00', 'shows "' + cellText('B5') + '"');

// 6. add a sheet
p = await tab('sheets'); let n0 = S().sheets.length;
setv(field(p, /name|sheet|new/, 'INPUT') || inputs(p).find(i => i.tagName === 'INPUT'), 'Data');
await click(p, /add|create|new/i);
step('add a sheet from the Sheets tab', S().sheets.length === n0 + 1 && S().sheets.some(s => s.name === 'Data'), S().sheets.map(s => s.name).join(','));
if (S().active !== 's1' && S().sheets.some(s => s.id === 's1')) { const back = [...p.querySelectorAll('button')].find(b => /^sheet1$/i.test(b.textContent.trim())); if (back) { back.click(); await sleep(60); } }
if (S().active !== 's1') App.store.set({ active: 's1' });

// 7. define a name and use it
p = await tab('names');
setv(field(p, /^(name|names).*|.*name.*/, 'INPUT') || inputs(p)[0], 'trip');
setv(field(p, /target|range|refers|ref/, 'INPUT') || inputs(p)[1], 'Sheet1!A1:A2');
await click(p, /add|define|save|create/i);
const named = S().names && /sheet1!a1:a2/i.test(S().names.trip || '');
await type('D5', '=SUM(trip)');
step('define the name trip = Sheet1!A1:A2 and use it in =SUM(trip)', named && cellText('D5') === '30', 'names ' + JSON.stringify(S().names) + ', D5 shows "' + cellText('D5') + '"');

// 8. find lists the cells holding the text
p = await tab('find');
setv(field(p, /find|search|query|text/, 'INPUT') || inputs(p).find(i => i.tagName === 'INPUT'), 'ab');
await click(p, /find|search/i); await sleep(100);
step('searching "ab" on the Find tab lists B1', has(document.getElementById('panel-find'), /\bB1\b/), '');

// 9. CSV export and import
p = await tab('csv');
let rangeIn = field(p, /range|export/, 'INPUT'); if (rangeIn) setv(rangeIn, 'A1:B3');
await click(p, /export|download|to csv/i); await sleep(100);
const ta = [...p.querySelectorAll('textarea')];
const exported = ta.some(t => /10/.test(t.value)) || /10,ab/.test(text(p));
step('export A1:B3 as CSV shows the values', exported, '');
const writable = ta.filter(t => !t.readOnly && !t.disabled);
const importTa = writable.find(t => /import|paste/.test(label(t))) || writable[writable.length - 1] || ta[ta.length - 1];
setv(importTa, '1,2\n3,4');
const atIn = field(p, /at|target|cell|start|paste/, 'INPUT'); if (atIn) setv(atIn, 'F1');
await click(p, /import|paste|load/i); await sleep(100);
step('import "1,2 / 3,4" at F1 fills F1..G2', raw('F1') === '1' && raw('G2') === '4', 'F1 "' + raw('F1') + '", G2 "' + raw('G2') + '"');

// 10. a bar chart from a range
p = await tab('chart');
const lab = field(p, /label|categor|x/, 'INPUT'); if (lab) setv(lab, 'D1:D3');
const dat = field(p, /data|value|series|y/, 'INPUT'); if (dat) setv(dat, 'E1:E3');
await click(p, /draw|update|render|chart|apply/i); await sleep(100);
step('the Chart tab draws one bar per value of E1:E3', document.querySelectorAll('#panel-chart svg rect').length >= 3, document.querySelectorAll('#panel-chart svg rect').length + ' rects');

// 11. insert a row and see the references move
p = await tab('rowscols');
const rowIn = field(p, /row|index|at|number|position/, 'INPUT'); if (rowIn) setv(rowIn, '2');
const insertedRow = await click(p, /insert row|add row|row.*insert|insert.*row/i);
step('insert a row at 2 moves A2 to A3 and rewrites A1+A2', insertedRow && raw('A3') === '20' && raw('A4') === '=A1+A3', 'A3 "' + raw('A3') + '", A4 "' + raw('A4') + '"');

// 12. stats of a range
p = await tab('stats');
setv(field(p, /range|cells|select/, 'INPUT') || inputs(p).find(i => i.tagName === 'INPUT'), 'A1:A4');
await click(p, /compute|show|update|stats|apply/i); await sleep(100);
step('the Stats tab sums A1:A4 to 60', has(document.getElementById('panel-stats'), /\b60\b/), '');

// 13. a validation rule and its violations
p = await tab('validation');
const vcell = field(p, /cell|addr|target/, 'INPUT'); if (vcell) setv(vcell, 'A3');
pick(inputs(p).find(i => i.tagName === 'SELECT'), /number/i);
const mn = field(p, /min/); if (mn) setv(mn, '0');
const mx = field(p, /max/); if (mx) setv(mx, '10');
await click(p, /add|set|save|apply/i); await sleep(100);
step('a number rule 0..10 on A3 lists A3 (20) as a violation', has(document.getElementById('panel-validation'), /\bA3\b/) && (sheet().rules || {}).A3 !== undefined, '');

// 14. arrow keys move the selection
await tab('grid'); if (td('B5')) { td('B5').click(); await sleep(60); }
key(td('B5') || document.querySelector('#panel-grid table') || document.body, 'ArrowDown');   // one event: it bubbles to the table
await sleep(100);
const selNow = (S().ui && (S().ui.selected || S().ui.cursor)) || (document.querySelector('#panel-grid td.selected') || {}).dataset && document.querySelector('#panel-grid td.selected').dataset.addr;
step('ArrowDown from B5 selects B6', selNow === 'B6' || (td('B6') && td('B6').classList.contains('selected')), 'selected ' + selNow);

// 15. the book is saved
const KEY = App.features.persist && App.features.persist.model && App.features.persist.model.KEY;
let saved = null; try { saved = JSON.parse(localStorage.getItem(KEY)); } catch (e) {}
step('the book is in localStorage under persist.model.KEY as version 2', !!saved && saved.version === 2 && Array.isArray(saved.sheets), KEY ? 'key ' + KEY : 'no KEY');

// 16. a conditional rule paints the cell
p = await tab('conditional');
const crange = field(p, /range|cells/, 'INPUT'); if (crange) setv(crange, 'A1:A4');
pick(inputs(p).find(i => i.tagName === 'SELECT'), /greater|gt|>/i);
const cval = field(p, /value|than|threshold/, 'INPUT'); if (cval) setv(cval, '15');
const ccls = field(p, /class|style|colou?r|name/, 'INPUT'); if (ccls) setv(ccls, 'hot');
await click(p, /add|apply|save|set/i); await sleep(100);
await tab('grid');
step('a "greater than 15" rule on A1:A4 gives A3 (20) the class hot', !!td('A3') && td('A3').classList.contains('hot'), td('A3') ? 'A3 classes "' + td('A3').className + '"' : 'no A3');
return { steps };
